#include <bits/stdc++.h>
using namespace std;

// 处理单组数据，返回每次操作后的异或和
vector<int> solve_case(const vector<long long>& a) {
    vector<long long> top;  // 每个桶的桶顶质量，保持非递减
    vector<int> height;     // 每个桶的高度
    vector<int> res;

    int cur_xor = 0;        // 当前所有桶高度的异或和

    for (long long x : a) {
        // 找到第一个桶顶质量 > x 的桶
        int pos = upper_bound(top.begin(), top.end(), x) - top.begin();

        if (pos == (int)top.size()) {
            // 新建一个桶
            top.push_back(x);
            height.push_back(1);
            cur_xor ^= 1;
        } else {
            // 放到已有桶上，更新桶顶质量和高度
            int old_h = height[pos];
            cur_xor ^= old_h;
            height[pos] = old_h + 1;
            cur_xor ^= height[pos];
            top[pos] = x;
        }

        res.push_back(cur_xor);
    }

    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        cin >> n;

        vector<long long> a(n);
        for (int i = 0; i < n; i++) {
            cin >> a[i];
        }

        vector<int> ans = solve_case(a);

        for (int i = 0; i < n; i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}
