// 处理单组数据，返回每次操作后的异或和
vector<int> solve_case(const vector<long long>& a) {
    vector<long long> top;  // 每个展示盒的盒顶闪耀值，保持非递减
    vector<int> height;     // 每个展示盒的层数
    vector<int> res;

    int cur_xor = 0;        // 当前所有展示盒层数的异或和

    for (long long x : a) {
        // 找到第一个盒顶闪耀值 > x 的展示盒
        int pos = upper_bound(top.begin(), top.end(), x) - top.begin();

        if (pos == (int)top.size()) {
            // 新建一个展示盒
            top.push_back(x);
            height.push_back(1);
            cur_xor ^= 1;
        } else {
            // 放到已有展示盒上，更新盒顶闪耀值和层数
            int old_h = height[pos];
            cur_xor ^= old_h;
            height[pos] = old_h + 1;
            cur_xor ^= height[pos];
            top[pos] = x;
        }

        res.push_back(cur_xor);
    }

    return res;
