### Python

```python
import sys
from bisect import bisect_right

# 处理单组数据，返回每次操作后的异或和
def solve_case(arr):
    top = []       # 每个展示盒的盒顶闪耀值，保持非递减
    height = []    # 每个展示盒的层数
    cur_xor = 0    # 当前所有展示盒层数的异或和
    res = []

    for x in arr:
        # 找到第一个盒顶闪耀值 > x 的展示盒
        pos = bisect_right(top, x)

        if pos == len(top):
            # 新建一个展示盒
            top.append(x)
            height.append(1)
            cur_xor ^= 1
        else:
            # 放到已有展示盒上，更新盒顶闪耀值和层数
            old_h = height[pos]
            cur_xor ^= old_h
            height[pos] = old_h + 1
            cur_xor ^= height[pos]
            top[pos] = x

        res.append(str(cur_xor))

    return res


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    output = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        arr = data[idx:idx + n]
        idx += n

        output.append(" ".join(solve_case(arr)))

    sys.stdout.write("\n".join(output))


if __name__ == "__main__":
    main()
