```java
import java.io.*;
import java.util.*;

public class Main {

    // 处理单组数据，返回答案字符串
    static String solveCase(int n, long[] arr) {
        long[] top = new long[n];   // 每个展示盒的盒顶闪耀值
        int[] height = new int[n];  // 每个展示盒的层数
        int piles = 0;              // 当前展示盒数
        int curXor = 0;             // 当前层数异或和

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < n; i++) {
            long x = arr[i];

            // 二分查找第一个盒顶闪耀值 > x 的展示盒位置
            int l = 0, r = piles;
            while (l < r) {
                int mid = (l + r) / 2;
                if (top[mid] > x) {
                    r = mid;
                } else {
                    l = mid + 1;
                }
            }

            int pos = l;

            if (pos == piles) {
                // 新建一个展示盒
                top[piles] = x;
                height[piles] = 1;
                piles++;
                curXor ^= 1;
            } else {
                // 放到已有展示盒上，更新盒顶闪耀值和层数
                int oldH = height[pos];
                curXor ^= oldH;
                height[pos] = oldH + 1;
                curXor ^= height[pos];
                top[pos] = x;
            }

            if (i > 0) sb.append(' ');
            sb.append(curXor);
        }

        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder output = new StringBuilder();

        int t = fs.nextInt();

        for (int tc = 0; tc < t; tc++) {
            int n = fs.nextInt();
            long[] arr = new long[n];

            for (int i = 0; i < n; i++) {
                arr[i] = fs.nextLong();
            }

            output.append(solveCase(n, arr));
            if (tc + 1 < t) output.append('\n');
        }

        System.out.print(output.toString());
    }

    // 数据量较大，使用基于 BufferedInputStream 的输入
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
